create extension if not exists pgcrypto;
create table if not exists public.user_state(user_id uuid primary key references auth.users(id) on delete cascade,payload jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.settings(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,theme text default 'dark',wheel_limit numeric default .5,reserve_pct numeric default .1,updated_at timestamptz default now());
create table if not exists public.watchlist(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,symbol text not null,notes text,created_at timestamptz default now());
create table if not exists public.wheels(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,symbol text not null,mode text not null check(mode in ('paper','live')),status text not null,shares integer,strike numeric,expiry date,source text,created_at timestamptz default now());
create table if not exists public.trades(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,wheel_id uuid references public.wheels(id) on delete cascade,side text not null,quantity numeric not null,price numeric not null,executed_at timestamptz default now());
create table if not exists public.dividends(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,symbol text not null,ex_date date,amount numeric,source text); 
create table if not exists public.snapshots(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,as_of timestamptz default now(),payload jsonb not null);
create table if not exists public.wheel_events(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,wheel_id uuid references public.wheels(id) on delete cascade,event_type text not null,payload jsonb not null,created_at timestamptz default now());
create table if not exists public.journal_entries(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,body text not null,created_at timestamptz default now());
create table if not exists public.market_cache(symbol text primary key,provider text not null,payload jsonb not null,as_of timestamptz not null,expires_at timestamptz not null);
do $$ declare t text; begin foreach t in array array['user_state','settings','watchlist','wheels','trades','dividends','snapshots','wheel_events','journal_entries','market_cache'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "own user state" on public.user_state for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "market cache read" on public.market_cache for select using(true);
do $$ declare t text; begin foreach t in array array['settings','watchlist','wheels','trades','dividends','snapshots','wheel_events','journal_entries'] loop execute format('create policy "owner %1$s" on public.%1$s for all using(owner_id=auth.uid()) with check(owner_id=auth.uid())',t); end loop; end $$;
